{
  "version": "1",
  "title": "Min-Heap Insertion of 3",
  "domain": "data-structures",
  "summary": "Inserting 3 into a min-heap involves appending it at the bottom-most right position and bubbling it up until the min-heap property is satisfied.",
  "entities": [
    {
      "id": "heapTree",
      "type": "tree",
      "label": "Min-Heap",
      "nodes": [
        { "id": "n5", "value": "5" },
        { "id": "n9", "value": "9", "parent": "n5" },
        { "id": "n7", "value": "7", "parent": "n5" },
        { "id": "n12", "value": "12", "parent": "n9" },
        { "id": "n10", "value": "10", "parent": "n9" }
      ]
    },
    {
      "id": "arr",
      "type": "array",
      "values": [5, 9, 7, 12, 10],
      "label": "Array Representation",
      "indices": true
    },
    {
      "id": "msg",
      "type": "text",
      "text": "",
      "role": "caption"
    }
  ],
  "layout": [
    {
      "rel": "place",
      "id": "heapTree",
      "region": "center"
    },
    {
      "rel": "below",
      "id": "arr",
      "of": "heapTree"
    },
    {
      "rel": "above",
      "id": "msg",
      "of": "heapTree"
    }
  ],
  "beats": [
    {
      "title": "Initial Min-Heap",
      "narration": "Here is our current min-heap. Every parent is smaller than or equal to its children.",
      "actions": [
        {
          "do": "create",
          "target": "heapTree",
          "effect": "draw"
        },
        {
          "do": "create",
          "target": "arr",
          "effect": "fade",
          "with": "previous"
        },
        {
          "do": "set",
          "target": "msg",
          "text": "Starting Min-Heap",
          "with": "previous"
        }
      ]
    },
    {
      "title": "Insert 3 at the bottom",
      "narration": "We always insert a new value at the next available position in the complete tree, right under 7.",
      "actions": [
        {
          "do": "morph",
          "target": "heapTree",
          "values": ["5", "9", "7", "12", "10", "3"]
        },
        {
          "do": "morph",
          "target": "arr",
          "values": [5, 9, 7, 12, 10, 3],
          "with": "previous"
        },
        {
          "do": "set",
          "target": "msg",
          "text": "Insert 3 as child of 7",
          "with": "previous"
        },
        {
          "do": "highlight",
          "target": "heapTree.n3",
          "state": "active",
          "hold": true
        }
      ]
    },
    {
      "title": "Compare 3 with parent 7",
      "narration": "We compare the new value 3 with its parent 7. Since 3 is smaller, it violates the min-heap property.",
      "actions": [
        {
          "do": "highlight",
          "target": [
            "heapTree.n3",
            "heapTree.n7"
          ],
          "state": "comparing",
          "hold": true
        },
        {
          "do": "set",
          "target": "msg",
          "text": "3 < 7, bubble up!"
        }
      ]
    },
    {
      "title": "Swap 3 and 7",
      "narration": "We swap 3 and its parent 7. Now 3 moves up to the parent position.",
      "actions": [
        {
          "do": "morph",
          "target": "heapTree",
          "values": ["5", "9", "3", "12", "10", "7"]
        },
        {
          "do": "morph",
          "target": "arr",
          "values": [5, 9, 3, 12, 10, 7],
          "with": "previous"
        },
        {
          "do": "highlight",
          "target": "heapTree.n3",
          "state": "active",
          "hold": true
        }
      ]
    },
    {
      "title": "Compare 3 with new parent 5",
      "narration": "Next, we compare 3 with its new parent, 5.",
      "actions": [
        {
          "do": "highlight",
          "target": [
            "heapTree.n3",
            "heapTree.n5"
          ],
          "state": "comparing",
          "hold": true
        },
        {
          "do": "set",
          "target": "msg",
          "text": "3 < 5, bubble up again!"
        }
      ]
    },
    {
      "title": "Swap 3 and 5",
      "narration": "Since 3 is smaller than 5, we swap them. 3 becomes the new root of the heap.",
      "actions": [
        {
          "do": "morph",
          "target": "heapTree",
          "values": ["3", "9", "5", "12", "10", "7"]
        },
        {
          "do": "morph",
          "target": "arr",
          "values": [3, 9, 5, 12, 10, 7],
          "with": "previous"
        },
        {
          "do": "highlight",
          "target": "heapTree.n3",
          "state": "sorted",
          "hold": true
        },
        {
          "do": "set",
          "target": "msg",
          "text": "Insertion complete: Min-heap property restored"
        }
      ]
    }
  ]
}
